// Example masking function for streaming records
function maskPII(record) {
  if (!record) return record;
  if (record.email) record.email = record.email.replace(/[^@]+@[^.]+(\..{2,})/g, "***@***.***");
  if (record.phone) record.phone = record.phone.replace(/\d(?=\d{4})/g, '*');
  return record;
}
```

